#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m, t;
    cin >> n >> m >> t;
    vector<string> g(n);
    for (auto &r : g) cin >> r;
    // counts[r][c] = infected neighbours so far; 'Q' marks a cell queued for the next day.
    vector<vector<int>> counts(n, vector<int>(m, 0));
    auto forNeighbours = [&](int r, int c, auto f) {
        for (int x = max(0, r - 1); x < min(n, r + 2); x++)
            for (int y = max(0, c - 1); y < min(m, c + 2); y++)
                if (x != r || y != c) f(x, y);
    };
    for (int r = 0; r < n; r++)
        for (int c = 0; c < m; c++)
            if (g[r][c] == 'X') forNeighbours(r, c, [&](int x, int y) { counts[x][y]++; });
    vector<pair<int, int>> front, following;
    for (int r = 0; r < n; r++)
        for (int c = 0; c < m; c++)
            if (g[r][c] == '.' && counts[r][c] >= t) front.push_back({r, c}), g[r][c] = 'Q';
    int days = 0;
    while (!front.empty()) {
        days++;
        following.clear();
        for (auto [r, c] : front) {
            g[r][c] = 'X';
            forNeighbours(r, c, [&](int x, int y) {
                counts[x][y]++;
                if (g[x][y] == '.' && counts[x][y] >= t) g[x][y] = 'Q', following.push_back({x, y});
            });
        }
        swap(front, following);
    }
    cout << days << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int n = Integer.parseInt(st.nextToken()), m = Integer.parseInt(st.nextToken());
        int t = Integer.parseInt(st.nextToken());
        char[][] g = new char[n][];
        for (int i = 0; i < n; i++) g[i] = st.nextToken().toCharArray();
        // counts[r][c] = infected neighbours so far; 'Q' marks a cell queued for the next day.
        int[][] counts = new int[n][m];
        for (int r = 0; r < n; r++)
            for (int c = 0; c < m; c++)
                if (g[r][c] == 'X')
                    for (int x = Math.max(0, r - 1); x < Math.min(n, r + 2); x++)
                        for (int y = Math.max(0, c - 1); y < Math.min(m, c + 2); y++)
                            if (x != r || y != c) counts[x][y]++;
        int[] front = new int[n * m], following = new int[n * m];
        int fs = 0;
        for (int r = 0; r < n; r++)
            for (int c = 0; c < m; c++)
                if (g[r][c] == '.' && counts[r][c] >= t) {
                    front[fs++] = r * m + c;
                    g[r][c] = 'Q';
                }
        int days = 0;
        while (fs > 0) {
            days++;
            int ns = 0;
            for (int i = 0; i < fs; i++) {
                int r = front[i] / m, c = front[i] % m;
                g[r][c] = 'X';
                for (int x = Math.max(0, r - 1); x < Math.min(n, r + 2); x++)
                    for (int y = Math.max(0, c - 1); y < Math.min(m, c + 2); y++) {
                        if (x == r && y == c) continue;
                        counts[x][y]++;
                        if (g[x][y] == '.' && counts[x][y] >= t) {
                            g[x][y] = 'Q';
                            following[ns++] = x * m + y;
                        }
                    }
            }
            int[] tmp = front;
            front = following;
            following = tmp;
            fs = ns;
        }
        System.out.println(days);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, m, t int
	fmt.Fscan(in, &n, &m, &t)
	g := make([][]byte, n)
	for i := range g {
		var row string
		fmt.Fscan(in, &row)
		g[i] = []byte(row)
	}
	// counts[r][c] = infected neighbours so far; 'Q' marks a cell queued for the next day.
	counts := make([][]int, n)
	for i := range counts {
		counts[i] = make([]int, m)
	}
	for r := 0; r < n; r++ {
		for c := 0; c < m; c++ {
			if g[r][c] != 'X' {
				continue
			}
			for x := max(0, r-1); x < min(n, r+2); x++ {
				for y := max(0, c-1); y < min(m, c+2); y++ {
					if x != r || y != c {
						counts[x][y]++
					}
				}
			}
		}
	}
	front := [][2]int{}
	for r := 0; r < n; r++ {
		for c := 0; c < m; c++ {
			if g[r][c] == '.' && counts[r][c] >= t {
				front = append(front, [2]int{r, c})
				g[r][c] = 'Q'
			}
		}
	}
	days := 0
	for len(front) > 0 {
		days++
		following := [][2]int{}
		for _, cell := range front {
			r, c := cell[0], cell[1]
			g[r][c] = 'X'
			for x := max(0, r-1); x < min(n, r+2); x++ {
				for y := max(0, c-1); y < min(m, c+2); y++ {
					if x == r && y == c {
						continue
					}
					counts[x][y]++
					if g[x][y] == '.' && counts[x][y] >= t {
						g[x][y] = 'Q'
						following = append(following, [2]int{x, y})
					}
				}
			}
		}
		front = following
	}
	fmt.Println(days)
}
